    vector<vector<int>> g2(n), gr2(n);
    for (int u = 0; u < n; ++u) {
        if (f[u] == 1) continue;
        for (int v : g[u]) {
            if (f[v] == 1) continue;
            g2[u].push_back(v);
            gr2[v].push_back(u);
        }
    }

    // Step 3: SCC on g2
    vector<int> order;
    vector<char> used(n, 0);
    function<void(int)> dfs1 = [&](int v) {
        used[v] = 1;
        for (int to : g2[v]) if (!used[to]) dfs1(to);
        order.push_back(v);
    };
    for (int i = 0; i < n; ++i)
        if (!used[i] && f[i] != 1)
            dfs1(i);

    vector<int> comp(n, -1);
    int compCnt = 0;
    function<void(int,int)> dfs2 = [&](int v, int c) {
        comp[v] = c;
        for (int to : gr2[v]) if (comp[to] == -1) dfs2(to, c);
    };
    for (int i = (int)order.size() - 1; i >= 0; --i) {
        int v = order[i];
        if (comp[v] == -1)
            dfs2(v, compCnt++);
    }

    if (compCnt == 0) {
        // No nodes except assignments
        for (int i = 0; i < n; ++i) cout << 0 << (i + 1 == n ? '\n' : ' ');
        return 0;
    }

    // Step 4: build condensation DAG
    vector<vector<int>> dag(compCnt), rdag(compCnt);
    for (int u = 0; u < n; ++u) {
        if (f[u] == 1 || comp[u] == -1) continue;
        for (int v : g2[u]) {
            if (comp[v] != comp[u]) {
                dag[comp[u]].push_back(comp[v]);
                rdag[comp[v]].push_back(comp[u]);
            }
        }
    }

