    vector<char> compCanReachUse(compCnt, 0);
    queue<int> q2;
    for (int v = 0; v < n; ++v) {
        if (f[v] == 2 && comp[v] != -1 && !compCanReachUse[comp[v]]) {
            compCanReachUse[comp[v]] = 1;
            q2.push(comp[v]);
        }
    }
    while (!q2.empty()) {
        int c = q2.front(); q2.pop();
        for (int pc : rdag[c]) {
            if (!compCanReachUse[pc]) {
                compCanReachUse[pc] = 1;
                q2.push(pc);
            }
        }
    }

    // Step 6: mark components that can reach an assignment (in original graph)
    vector<char> compCanReachAssign(compCnt, 0);
    queue<int> q3;
    for (int v = 0; v < n; ++v) {
        if (f[v] == 1) {
            for (int u : gr[v]) {
                if (comp[u] != -1 && !compCanReachAssign[comp[u]]) {
                    compCanReachAssign[comp[u]] = 1;
                    q3.push(comp[u]);
                }
            }
        }
    }
    while (!q3.empty()) {
        int c = q3.front(); q3.pop();
        for (int pc : rdag[c]) {
            if (!compCanReachAssign[pc]) {
                compCanReachAssign[pc] = 1;
                q3.push(pc);
            }
        }
    }

    // Step 7: answer
    vector<int> ans(n, 0);
    for (int v = 0; v < n; ++v) {
        if (f[v] == 1) {
            // assignment node itself: needs path from it to use with no other assignments
            if (canReachUse[v]) ans[v] = 1;
        } else if (comp[v] != -1) {
            int c = comp[v];
            if (compCanReachUse[c] && !compCanReachAssign[c]) ans[v] = 1;
        }
    }

    for (int i = 0; i < n; ++i)
        cout << ans[i] << (i + 1 == n ? '\n' : ' ');
    return 0;
}

