        for (int to : g[v]) if (!used[to]) dfs1(to);
        order.push_back(v);
    };
    for (int i = 0; i < n; ++i)
        if (!used[i]) dfs1(i);

    int scc_cnt = 0;
    function<void(int)> dfs2 = [&](int v) {
        comp[v] = scc_cnt;
        for (int to : gr[v]) if (comp[to] == -1) dfs2(to);
    };
    for (int i = n - 1; i >= 0; --i) {
        int v = order[i];
        if (comp[v] == -1) {
            dfs2(v);
            ++scc_cnt;
        }
    }

    // Build condensation DAG
    vector<vector<int>> dag(scc_cnt), rdag(scc_cnt);
    vector<int> has_assign(scc_cnt, 0), has_use(scc_cnt, 0);
    for (int v = 0; v < n; ++v) {
        int c = comp[v];
        if (f[v] == 1) has_assign[c] = 1;
        if (f[v] == 2) has_use[c] = 1;
        for (int to : g[v]) {
            int c2 = comp[to];
            if (c != c2) {
                dag[c].push_back(c2);
                rdag[c2].push_back(c);
            }
        }
    }

    // Remove duplicate edges
    for (int i = 0; i < scc_cnt; ++i) {
        sort(dag[i].begin(), dag[i].end());
        dag[i].erase(unique(dag[i].begin(), dag[i].end()), dag[i].end());
        sort(rdag[i].begin(), rdag[i].end());
        rdag[i].erase(unique(rdag[i].begin(), rdag[i].end()), rdag[i].end());
    }

