    vector<int> indeg(scc_cnt, 0);
    for (int i = 0; i < scc_cnt; ++i)
        for (int to : dag[i]) ++indeg[to];

    queue<int> q;
    for (int i = 0; i < scc_cnt; ++i)
        if (indeg[i] == 0) q.push(i);

    vector<int> topo;
    while (!q.empty()) {
        int v = q.front(); q.pop();
        topo.push_back(v);
        for (int to : dag[v]) {
            if (--indeg[to] == 0) q.push(to);
        }
    }

