    vector<char> canReachUse(scc_cnt, 0);
    for (int i = 0; i < scc_cnt; ++i)
        if (has_use[i]) canReachUse[i] = 1;

    for (int i = (int)topo.size() - 1; i >= 0; --i) {
        int v = topo[i];
        if (has_assign[v]) continue; // cannot propagate past another assign
        for (int to : dag[v]) {
            if (canReachUse[to]) canReachUse[v] = 1;
        }
    }

    // Reverse DP: can be reached from some assign without passing another assign
    vector<char> canReachFromAssign(scc_cnt, 0);
    for (int i = 0; i < scc_cnt; ++i)
        if (has_assign[i]) canReachFromAssign[i] = 1;

    for (int v : topo) {
        if (!canReachFromAssign[v]) continue;
        for (int to : dag[v]) {
            if (has_assign[to]) continue; // another assign breaks the chain
            if (!canReachFromAssign[to]) {
                canReachFromAssign[to] = 1;
            }
        }
    }

    // Combine conditions
    vector<int> ans(n, 0);
    for (int v = 0; v < n; ++v) {
        int c = comp[v];
        if (canReachFromAssign[c] && canReachUse[c]) ans[v] = 1;
    }

    for (int i = 0; i < n; ++i) {
        cout << ans[i] << (i + 1 == n ? '\n' : ' ');
    }

    return 0;
}

