        gr[b].push_back(a);
    }

    // Kosaraju
    for (int i = 1; i <= n; ++i)
        if (!used[i]) dfs1(i);

    int compCnt = 0;
    for (int i = order[0]; i >= 1; --i) {
        int v = order[i];
        if (!comp[v]) {
            ++compCnt;
            dfs2(v, compCnt);
        }
    }

    // Build condensation DAG
    for (int v = 1; v <= n; ++v) {
        int cv = comp[v];
        if (f[v] == 1) hasAssign[cv] = true;
        if (f[v] == 2) hasUse[cv] = true;
        for (int to : g[v]) {
            int cu = comp[to];
            if (cv != cu) {
                dag[cv].push_back(cu);
                rdag[cu].push_back(cv);
            }
        }
    }

    // Remove duplicate edges
    for (int i = 1; i <= compCnt; ++i) {
        sort(dag[i].begin(), dag[i].end());
        dag[i].erase(unique(dag[i].begin(), dag[i].end()), dag[i].end());
        sort(rdag[i].begin(), rdag[i].end());
        rdag[i].erase(unique(rdag[i].begin(), rdag[i].end()), rdag[i].end());
    }

    // Topological order of condensation DAG
    vector<int> topo;
    topo.reserve(compCnt);
    vector<int> indegree(compCnt + 1, 0);
    for (int i = 1; i <= compCnt; ++i)
        for (int to : dag[i]) indegree[to]++;

    queue<int> q;
    for (int i = 1; i <= compCnt; ++i)
        if (indegree[i] == 0) q.push(i);

    while (!q.empty()) {
        int v = q.front(); q.pop();
        topo.push_back(v);
        for (int to : dag[v]) {
            if (--indegree[to] == 0) q.push(to);
        }
    }

    // DP forward: from assign to use without another assign
    for (int v : topo) {
        bool fromAssign = hasAssign[v];
        for (int p : rdag[v])
            if (goodFromAssign[p]) fromAssign = true;
        goodFromAssign[v] = fromAssign;
    }

    // DP backward: to use without another assign
    for (int i = (int)topo.size() - 1; i >= 0; --i) {
        int v = topo[i];
        bool toUse = hasUse[v];
        for (int to : dag[v])
            if (goodToUse[to] && !hasAssign[to]) toUse = true;
        goodToUse[v] = toUse;
    }

    // Determine interesting components
    for (int i = 1; i <= compCnt; ++i) {
        if (goodFromAssign[i] && goodToUse[i]) interestingComp[i] = true;
    }

    // Output per node
    for (int i = 1; i <= n; ++i) {
        cout << (interestingComp[comp[i]] ? 1 : 0);
        if (i < n) cout << '\n';
    }

    return 0;
}

