#include <bits/stdc++.h>
using namespace std;

/*
We need states that lie on some path:
  assign (1) ... (no other assign) ... use (2)
We can have ignore(0) or use(2) in between, but no assign(1).

Idea:
1) Build graph and reverse graph.
2) From all use-states (f[i] == 2), BFS/DFS on reverse graph using only edges
   that do NOT pass through assign-states (except starting nodes).
   That gives us all states that can reach some use without encountering assign.
3) From all assign-states (f[i] == 1), BFS/DFS on forward graph, again only
   through non-assign states (except starting nodes).
   That gives us all states reachable from some assign without encountering assign.
4) Answer[i] = 1 if state i is both reachable from some assign (step 3)
   and can reach some use (step 2), and there exists a path assign->...->use
   with no intermediate assign. The intersection of the two visited sets
   ensures that.

We must allow:
- starting at assign node in step 3 even though it's assign
- starting at use node in step 2 even though it's use
- but we must not traverse *through* assign nodes as intermediates.
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<int> f(n);
    for (int i = 0; i < n; ++i) cin >> f[i];

    vector<vector<int>> g(n), gr(n);
    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        --a; --b;
        g[a].push_back(b);
        gr[b].push_back(a);
    }

    // Step 2: reverse BFS from uses, avoiding passing through assigns
    vector<char> canReachUse(n, 0);
    queue<int> q;

    for (int i = 0; i < n; ++i) {
        if (f[i] == 2) {
            canReachUse[i] = 1;
            q.push(i);
        }
    }

    while (!q.empty()) {
        int v = q.front(); q.pop();
        for (int u : gr[v]) {
            if (canReachUse[u]) continue;
            if (f[u] == 1) continue; // cannot pass through another assign
            canReachUse[u] = 1;
            q.push(u);
        }
    }

    // Step 3: forward BFS from assigns, avoiding passing through assigns
    vector<char> fromAssign(n, 0);

    for (int i = 0; i < n; ++i) {
        if (f[i] == 1) {
            if (!fromAssign[i]) {
                fromAssign[i] = 1;
                q.push(i);
            }
        }
    }

    while (!q.empty()) {
        int v = q.front(); q.pop();
        for (int u : g[v]) {
            if (fromAssign[u]) continue;
            if (f[u] == 1) continue; // cannot pass through another assign
            fromAssign[u] = 1;
            q.push(u);
        }
    }

    // Result: intersection
    for (int i = 0; i < n; ++i) {
        int ans = (fromAssign[i] && canReachUse[i]) ? 1 : 0;
        cout << ans << (i + 1 == n ? '\n' : ' ');
    }

    return 0;
}
