#include <bits/stdc++.h>
using namespace std;

/*
We need states v that lie on some path:
  assign (1) ... (no other assign) ... use (2)
We must ensure no other assign on the path between the chosen assign and use.

Idea:
For each assign node s, we propagate a "clean" reachability where we stop
whenever we meet another assign (including s itself only as start).
But doing this per assign is too big.

Observation:
We only care about paths that do not pass through another assign.
So we consider the graph with all assign nodes removed as internal nodes.
Assign nodes can only be start points, and use nodes only endpoints.

We can:
1) Build graph G.
2) Build reduced graph G' by removing all assign nodes as intermediates:
   - For each edge u->v:
       if f[u] != 1 and f[v] != 1: keep edge u->v
   Assign nodes have no outgoing edges in G'.
3) From all use nodes (f[i]==2), run reverse BFS/DFS on reversed G'
   to find all nodes that can reach some use without passing an assign.
   Let good[i]=1 for such nodes.
4) Now, a node v is interesting if:
   - v is assign node and there exists some path from v to a use without
     another assign: i.e., some neighbor in G' reachable to use.
   - or v is non-assign node and lies on some such path between assign and use:
     i.e., good[v]==1 and there exists some assign node s that can reach v
     without another assign. That means v is reachable from some assign in G'.

To compute reachability from assigns without passing another assign:
   - On G', we start BFS/DFS from all neighbors of assign nodes? No, we need
     to include assign nodes themselves as interesting if they can reach use.
   - We'll create a super-source S connecting to all neighbors of assign nodes
     and track which nodes are reachable from some assign.

But we also need to know for each node if it is reachable from at least one assign.
We can:
   - Build G' as before.
   - Create a queue with all neighbors v of each assign node u (edges u->v where v not assign).
     Mark reachable_from_assign[v]=true, BFS over G'.
   - Assign nodes themselves: if any neighbor v of u has good[v]==1 (i.e., v can reach use),
     then u is interesting.

For intermediate nodes:
   - Node x (non-assign) is interesting if good[x]==1 and reachable_from_assign[x]==1.

Edge cases:
   - Direct assign->use edge: u assign, v use.
     v is non-assign (use) so in G' edge u->v exists (since v not assign).
     good[v]=1 (use).
     reachable_from_assign[v]=1 via BFS starting from v as neighbor of assign.
     So v interesting.
     u assign: neighbor v has good[v]==1, so u interesting.

   - Path starting with assign and no edges (single node) and used in same node? Not allowed
     since a node cannot be both assign and use simultaneously (fi is single value).

Complexity: O(n+m).

*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;
    vector<int> f(n);
    for (int i = 0; i < n; ++i) cin >> f[i];

    vector<vector<int>> g(n), gr(n);
    vector<pair<int,int>> edges;
    edges.reserve(m);
    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        --a; --b;
        edges.push_back({a,b});
    }

    // Build reduced graph G' without internal assigns
    for (auto &e : edges) {
        int u = e.first, v = e.second;
        if (f[u] != 1 && f[v] != 1) {
            g[u].push_back(v);
            gr[v].push_back(u);
        }
    }

    // good[i]: can reach some use without passing assign
    vector<char> good(n, 0);
    queue<int> q;

    // Start from all use nodes (f[i]==2)
    for (int i = 0; i < n; ++i) {
        if (f[i] == 2) {
            good[i] = 1;
            q.push(i);
        }
    }

    // Reverse BFS on G'
    while (!q.empty()) {
        int v = q.front(); q.pop();
        for (int u : gr[v]) {
            if (!good[u]) {
                good[u] = 1;
                q.push(u);
            }
        }
    }

    // reachable_from_assign[i]: reachable from some assign via G'
    vector<char> fromAssign(n, 0);
    queue<int> qa;

    // For each assign node, push its non-assign neighbors as BFS sources
    vector<char> inQueue(n, 0);
    for (auto &e : edges) {
        int u = e.first, v = e.second;
        if (f[u] == 1 && f[v] != 1) {
            if (!fromAssign[v]) {
                fromAssign[v] = 1;
                qa.push(v);
                inQueue[v] = 1;
            }
        }
    }

    while (!qa.empty()) {
        int v = qa.front(); qa.pop();
        inQueue[v] = 0;
        for (int to : g[v]) {
            if (!fromAssign[to]) {
                fromAssign[to] = 1;
                if (!inQueue[to]) {
                    qa.push(to);
                    inQueue[to] = 1;
                }
            }
        }
    }

    vector<int> ans(n, 0);

    // Non-assign nodes
    for (int i = 0; i < n; ++i) {
        if (f[i] != 1) {
            if (good[i] && fromAssign[i]) ans[i] = 1;
        }
    }

    // Assign nodes: check if they have a neighbor that is good
    for (auto &e : edges) {
        int u = e.first, v = e.second;
        if (f[u] == 1 && f[v] != 1 && good[v]) {
            ans[u] = 1;
        }
    }

    for (int i = 0; i < n; ++i) {
        cout << ans[i] << (i + 1 == n ? '\n' : ' ');
    }

    return 0;
}
